if(!defined('CONCILIACION_VISTA') || empty($puedeExcepcion)) { http_response_code(403); exit; }
$q=$pdo->prepare('SELECT e.saldo_final-(e.saldo_inicial+COALESCE(SUM(t.credito-t.debito),0)) diferencia FROM estados_cuenta e LEFT JOIN transacciones_estado_cuenta t ON t.id_estado_cienta=e.id WHERE e.id=? GROUP BY e.id'); $q->execute([$eid]); $diferenciaExcepcional=$q->fetchColumn();
$q=$pdo->prepare('SELECT a.*,u.nombre_completo FROM conciliacion_ajustes a JOIN usuarios u ON u.id=a.usuario_id WHERE a.estado_cuenta_id=? ORDER BY a.id'); $q->execute([$eid]); $ajustes=$q->fetchAll();
?>
<hr><details><summary><strong>Ajustes documentados y cierre excepcional</strong></summary>
<p>Acceso autorizado para este estado. Estos registros son ajustes de conciliación; no modifican el archivo bancario ni el depósito. Los vínculos pendientes de aprobación y movimientos sin resolver deben atenderse antes del cierre.</p>
<p>Diferencia de saldo original: <strong><?=ce($diferenciaExcepcional??'No calculable sin saldos')?></strong> <?=ce($seleccion['MONEDA'])?>. Un importe positivo aumenta el saldo conciliado y uno negativo lo disminuye.</p>
